(7575298, 1216734, 65234, '<td valign="top">How, cool! What an intriguing little critter. Nicely captured, too. Like he''s reaching for help.</td>', 'How, cool! What an intriguing little critter. Nicely captured, too. Like he''s reaching for help.', '2018-07-01 14:06:56.000000', NULL, 1),
(7575300, 1217114, 65234, '<td valign="top">At first I thought I was looking at mist, but then I realized it was a smoldering fire. How poignant, with that leaning stone and what I''m assuming is a firefighter in the background. Well captured.</td>', 'At first I thought I was looking at mist, but then I realized it was a smoldering fire. How poignant, with that leaning stone and what I''m assuming is a firefighter in the background. Well captured.', '2018-07-01 14:09:17.000000', NULL, 1),
