INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7578622, 1217156, 67258, '<td valign="top">Astounded this do better!</td>', 'Astounded this do better!', '2018-07-08 06:13:19.000000', NULL, 0),
(7578645, 1216324, 194290, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by salmiakki:</b></div><hr/><i> When I visited here we had horrible dull grey skies and no water in the terraces.  Although an impressive place to visit, I was disappointed with my images from here.  Well done on the ribbon. </i></td></tr></table> <br/> <br/>i went there last year in May and only few of the steps were watered. i checked with the locals there and they told by mid of june only most of the steps will be watered. so i returned this year in june and i was lucky with the sky, the previous day had no colors, but next day was awesome view. Thanks for your comment.</td>', 'Originally posted by salmiakki: When I visited here we had horrible dull grey skies and no water in the terraces.  Although an impressive place to visit, I was disappointed with my images from here.  Well done on the ribbon.   i went there last year in May and only few of the steps were watered. i checked with the locals there and they told by mid of june only most of the steps will be watered. so i returned this year in june and i was lucky with the sky, the previous day had no colors, but next day was awesome view. Thanks for your comment.', '2018-07-08 08:58:23.000000', NULL, 0),
(7578659, 1216625, 67145, '<td valign="top">many congrats Lev .. what a wonderful photo .. and i''m so glad you got recognized in the challenge with that ribbon .. :)<br/>loved your story btw ... :)</td>', 'many congrats Lev .. what a wonderful photo .. and i''m so glad you got recognized in the challenge with that ribbon .. :)loved your story btw ... :)', '2018-07-08 09:22:50.000000', NULL, 0),
